def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    try:
        lines = []
        if header is not None:
            lines.append(header)

        for point in self.points:
            if not isinstance(point, tuple) or len(point) != 2:
                raise ValueError("Each point must be a tuple of (coordinate, value)")

            coord, value = point
            if isinstance(coord, tuple):
                coord_str = separator.join(map(str, coord))
            else:
                coord_str = str(coord)

            if isinstance(value, tuple):
                value_str = separator.join(map(str, value))
            else:
                value_str = str(value)

            lines.append(f"{coord_str}{separator}{value_str}")

        return "\n".join(lines)

    except Exception as e:
        raise RuntimeError(f"Error converting graph to CSV: {e}")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        if not isinstance(coord_name, str):
            raise ValueError("coord_name must be a string")

        # Assuming self.err_indices is a dictionary mapping coordinate names to error indices
        if not hasattr(self, 'err_indices') or not isinstance(self.err_indices, dict):
            raise AttributeError("self.err_indices must be a dictionary")

        err_indices = self.err_indices.get(coord_name)
        if err_indices is None:
            raise KeyError(f"No error indices found for coordinate: {coord_name}")

        if not isinstance(err_indices, list):
            raise ValueError(f"Error indices for {coord_name} must be a list")

        return err_indices

    except (ValueError, AttributeError, KeyError) as e:
        print(f"Error: {e}")
        return []

def _update_context(self, context):
    if not isinstance(context, dict):
        raise ValueError("context must be a dictionary")

    if 'error' not in context:
        context['error'] = {}

    # Assuming self has attributes E, t, error_E_low as mentioned in the docstring
    # and error names are simplified to "x", "y", "z"
    error_names = ["x", "y", "z"]
    errors = {
        "E": "error_E_low"
    }

    for error_name, error_attr in errors.items():
        if hasattr(self, error_attr):
            error_value = getattr(self, error_attr)
            if error_value is not None:
                context['error'][error_name] = {"index": error_value}

def integral(bins, edges):
    if not isinstance(bins, (list, tuple)) or not isinstance(edges, (list, tuple)):
        raise ValueError("Both bins and edges must be lists or tuples.")
    if len(bins) != len(edges) - 1:
        raise ValueError("The number of bins must be one less than the number of edges.")
    if any(not isinstance(x, (int, float)) for x in bins + edges):
        raise ValueError("All elements in bins and edges must be numbers.")
    if edges != sorted(edges):
        raise ValueError("Edges must be in non-decreasing order.")

    total = 0.0
    for i in range(len(bins)):
        width = edges[i + 1] - edges[i]
        total += bins[i] * width
    return total

