def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")

    if level == 0:
        return {}

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif d1[key] != d2[key]:
            diff[key] = d1[key]

    return diff

def fill(self, coord, weight=1):
    try:
        if not isinstance(coord, tuple) or not all(isinstance(c, int) for c in coord):
            raise ValueError("Coordinate must be a tuple of integers.")
        if weight < 0:
            raise ValueError("Weight must be a non-negative number.")

        if all(0 <= c < dim for c, dim in zip(coord, self.shape)):
            self.histogram[coord] += weight
    except Exception as e:
        print(f"An error occurred: {e}")

def _validate_labels(labels):
    import re
    from collections.abc import Hashable

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(f"Validation errors: {messages}")

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'expected hashable object'})
            continue

        key_str = str(key)
        if not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

        if not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})
            continue

        if not value_regex.match(value):
            errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    identifying_fields = {'apiVersion', 'kind', 'metadata'}

    for key, value in manifest_dict.items():
        if first_level and key in identifying_fields:
            observer_schema[key] = value
        elif isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

