    num_objects = 0
    good_objects = 0

    try:
        # Assuming self.root is the starting point of the hierarchy
        for obj in self.root.iterate_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj.id} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
