def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser
    parser_a = subparsers.add_parser('a', help='Subparser A')
    parser_a.add_argument('--foo', type=int, help='Foo argument for subparser A')

    # Another example subparser
    parser_b = subparsers.add_parser('b', help='Subparser B')
    parser_b.add_argument('--bar', type=str, help='Bar argument for subparser B')

    # Global arguments
    parser.add_argument('--global_arg', type=str, help='Global argument')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        # Handle the case where argument parsing fails
        return {}

    result = {}
    if args.subparser_name:
        result[args.subparser_name] = args
    else:
        result['global'] = args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            # Parse known arguments for the current subparser
            parsed, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed
            remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, store None and continue with other subparsers
            parsed_results[subparser_name] = None

    return parsed_results, remaining_arguments

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_values(key, value1, value2):
        if isinstance(value1, MappingNode) and isinstance(value2, MappingNode):
            merged_value = value1.value.copy()
            for k2, v2 in value2.value:
                found = False
                for i, (k1, v1) in enumerate(merged_value):
                    if k1.value == k2.value:
                        merged_value[i] = (k2, merge_values(k2, v1, v2))
                        found = True
                        break
                if not found:
                    merged_value.append((k2, v2))
            return MappingNode(tag=value1.tag, value=merged_value)
        else:
            return value2

    merged_dict = {}
    for key, value in nodes:
        if key.value in merged_dict:
            merged_dict[key.value] = merge_values(key, merged_dict[key.value], value)
        else:
            merged_dict[key.value] = value

    return [(ScalarNode(tag=key.tag, value=key_value), value) for key_value, value in merged_dict.items()]

def parse_arguments(*arguments):
    import argparse
    parser = argparse.ArgumentParser(description='Parse command-line arguments.')
    try:
        # Assuming the first argument is the script name, we skip it
        parsed_args = parser.parse_args(arguments[1:])
        return parsed_args
    except Exception as e:
        parser.error(f"Error parsing arguments: {e}")
        return None

def parser_flags(parser):
    try:
        flags = [action.option_strings for action in parser._actions if action.option_strings]
        flattened_flags = [flag for sublist in flags for flag in sublist]
        return ' '.join(flattened_flags)
    except AttributeError:
        raise ValueError("The provided object is not an instance of argparse.ArgumentParser")

def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser
    parser_a = subparsers.add_parser('a', help='Subparser A')
    parser_a.add_argument('--foo', type=int, help='Foo argument for subparser A')

    # Another example subparser
    parser_b = subparsers.add_parser('b', help='Subparser B')
    parser_b.add_argument('--bar', type=str, help='Bar argument for subparser B')

    # Global arguments
    parser.add_argument('--global_arg', type=str, help='Global argument')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        # Handle the case where argument parsing fails
        return {}

    result = {}
    if args.subparser_name:
        result[args.subparser_name] = args
    else:
        result['global'] = args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            # Parse known arguments for the current subparser
            parsed, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed
            remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, store None and continue with other subparsers
            parsed_results[subparser_name] = None

    return parsed_results, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    suffixes = {'K': 1000, 'M': 1000**2, 'G': 1000**3, 'T': 1000**4}
    if size[-1].upper() in suffixes:
        number = size[:-1]
        suffix = size[-1].upper()
    else:
        number = size
        suffix = ''

    try:
        number = float(number)
    except ValueError:
        raise ValueError(f"Invalid number in size string: {size}")

    if suffix:
        return int(number * suffixes[suffix])
    else:
        return int(number)

def _dictsum(dicts):
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the iterable must be dictionaries.")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise ValueError("All dictionary values must be numbers.")
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise ValueError("URL must be a string")
    if not isinstance(url_args, dict):
        raise ValueError("url_args must be a dictionary")

    try:
        for key, value in url_args.items():
            placeholder = f"{{{key}}}"
            if placeholder in url:
                url = url.replace(placeholder, str(value))
        return url
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing URL arguments: {e}")

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        return val.strip().lower() in {'none', 'null', 'nil', 'n/a', ''}
    return False

