def was_processed(processed, path_name, verbose):
    try:
        import os
        abs_path = os.path.abspath(path_name)
        if abs_path in processed:
            if verbose:
                print(f"Path '{abs_path}' has already been processed.")
            return True
        else:
            processed.add(abs_path)
            return False
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet list cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise ValueError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise ValueError("register_value must be a string")

    try:
        for key, value in flow_params.items():
            if isinstance(value, dict):
                _replace_register(value, register_number, register_value)
            elif value == register_value:
                flow_params[key] = register_number
    except Exception as e:
        raise RuntimeError(f"An error occurred while replacing register: {e}")

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("The 'value' parameter must be a string.")
    if not isinstance(arg, str):
        raise ValueError("The 'arg' parameter must be a string.")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("Input must be a class")
    subclasses_list = []
    for subclass in cls.__subclasses__():
        subclasses_list.append(subclass)
        subclasses_list.extend(subclasses(subclass))
    return subclasses_list

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Both string and alphabet must be non-empty.")

    base = len(alphabet)
    result = 0

    for char in string:
        if char not in alphabet:
            raise ValueError(f"Character '{char}' not found in the alphabet.")
        digit_value = alphabet.index(char)
        result = result * base + digit_value

    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        return os.name == 'posix' and 'darwin' in os.uname()
    except AttributeError:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise ValueError("Input must be a string")
    return name.strip('"').strip("'")

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = [line.split()[-1] for line in result.stdout.strip().split('\n') if line]

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string separated by commas
        return ','.join(ignored_files)

    except subprocess.CalledProcessError as e:
        # Handle the case where the git command fails
        return f"Error: {e.stderr.strip()}"
    except Exception as e:
        # Handle any other exceptions
        return f"An unexpected error occurred: {str(e)}"

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        parts = frequency.split()
        if len(parts) != 2:
            raise ValueError("Frequency must be in the format 'number unit'")

        number = int(parts[0])
        unit = parts[1].lower()

        if unit in ['second', 'seconds']:
            return datetime.timedelta(seconds=number)
        elif unit in ['minute', 'minutes']:
            return datetime.timedelta(minutes=number)
        elif unit in ['hour', 'hours']:
            return datetime.timedelta(hours=number)
        elif unit in ['day', 'days']:
            return datetime.timedelta(days=number)
        elif unit in ['week', 'weeks']:
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")

    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid frequency format: {frequency}") from e

def make_find_paths(find_paths):
    def is_pattern(s):
        return '*' in s or '?' in s or '[' in s or ']' in s

    transformed_paths = []
    for path in find_paths:
        if not is_pattern(path) and ':' not in path:
            # Transform path fragment into a glob pattern
            transformed_path = f'sh:**/*{path}*/**'
        else:
            # Pass through existing patterns or paths with colon untouched
            transformed_path = path
        transformed_paths.append(transformed_path)
    return transformed_paths

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        return os.environ.get('MSYSTEM') == 'MINGW64' and os.name == 'nt'
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    try:
        if os.path.exists(config_filename) and not overwrite:
            raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False.")

        os.makedirs(os.path.dirname(config_filename), exist_ok=True)

        with open(config_filename, 'w') as config_file:
            config_file.write(rendered_config)

        os.chmod(config_filename, mode)

    except Exception as e:
        raise Exception(f"An error occurred while writing the configuration file: {e}")

def oneline(script, separator=" && "):
    """
    converts a script to one line command.
    This is useful to run a single ssh command and pass a one line script.

    :param script: A string or a list of strings representing the script.
    :param separator: A string used to separate commands in the one-liner.
    :return: A single string with the script commands separated by the separator.
    """
    try:
        if isinstance(script, str):
            script = script.splitlines()
        elif not isinstance(script, list):
            raise ValueError("Script must be a string or a list of strings.")

        # Filter out empty lines
        script = [line.strip() for line in script if line.strip()]

        return separator.join(script)
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher
    except ValueError:
        raise ValueError("Matcher must be a tuple containing the name and an optional default value.")

    value = os.getenv(name, default)
    if value is None:
        raise EnvironmentError(f"Environment variable '{name}' is not defined and no default value was provided.")

    return value

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list of strings")

    processed_list = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All elements in the list must be strings")
        if len(item) > 1 and item.endswith(os.sep):
            item = item[:-1]
        processed_list.append(item)

    return processed_list

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise ValueError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        regex_pattern = re.compile(pattern)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {e}")

    return regex_pattern

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("Commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("Arguments must be a list of strings.")

    full_command = commands + args
    try:
        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(full_command, cwd=cwd, env=env, capture_output=True, text=True, stderr=stderr, check=True)

        if verbose:
            print("Command output:", result.stdout)

        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with error:", e.stderr)
        raise
    except Exception as e:
        if verbose:
            print("An error occurred:", str(e))
        raise

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        ipaddress.IPv4Address(target)
        return True
    except (ipaddress.AddressValueError, ValueError):
        return False

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()
    try:
        # Find all nodes that are not children in any (child, prop, parent) triple
        children = {triple[0] for triple in graph.triples((None, prop, None))}
        parents = {triple[2] for triple in graph.triples((None, prop, None))}
        roots.update(parents - children)
        return roots
    except Exception as e:
        raise ValueError(f"An error occurred while finding roots: {e}")

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            dumper = yaml.SafeDumper
        return yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True).strip()
    except Exception as e:
        raise ValueError(f"Error dumping object to string: {e}")

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    try:
        if not isinstance(shape, tuple):
            raise ValueError("Shape must be a tuple.")
        if not all(isinstance(dim, int) and dim > 0 for dim in shape):
            raise ValueError("All dimensions in shape must be positive integers.")
        if not isinstance(dtype, np.dtype):
            raise ValueError("Dtype must be a numpy.dtype.")
        return np.empty(shape, dtype=dtype)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    import json
    import logging

    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                config_dict[filename] = config
        except FileNotFoundError:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=(), exc_info=True))
        except json.JSONDecodeError as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"JSON decode error in {filename}: {e}", args=(), exc_info=True))
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Unexpected error in {filename}: {e}", args=(), exc_info=True))

    # Apply overrides
    for key, value in overrides.items():
        for config in config_dict.values():
            if key in config:
                config[key] = value

    # Resolve environment variables if required
    if resolve_env:
        for config in config_dict.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    config[key] = os.getenv(env_var, value)

    return config_dict, log_records

def from_ticks(cls, ticks, tz=None):
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
    seconds, nanoseconds = divmod(ticks, 1000000000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return cls(hours, minutes, seconds, nanoseconds, tz)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if not isinstance(values, (list, tuple, set)):
        raise ValueError("Values must be an iterable of strings.")

    for value in values:
        if not isinstance(value, str):
            raise ValueError("All values must be strings.")
        if not value.isascii():
            raise ValueError("All string values must be ASCII.")

    # Assuming Bookmarks is a class that can be initialized with a list of strings
    return cls(values)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    try:
        if isinstance(seq, (list, tuple, str, bytes, bytearray)):
            return (seq, type(seq))
        else:
            raise TypeError("Provided object is not a recognized sequence type.")
    except Exception as e:
        return (None, type(None))

def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or recompute:
            self._scale = self._compute_scale()
        return self._scale
    else:
        if not isinstance(other, float):
            raise TypeError("The scale factor must be a float.")
        if self._scale == 0:
            raise LenaValueError("Cannot rescale a histogram with scale equal to zero.")
        self._scale = other

def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")
        scale_factor = other / self._scale
        if len(self._data) == 0:
            raise LenaValueError("Graph has no data to rescale.")
        for i in range(len(self._data)):
            if len(self._data[i]) == 0:
                continue
            last_index = len(self._data[i][-1]) - 1
            self._data[i][-1][last_index] *= scale_factor
            if len(self._data[i]) > 1 and len(self._data[i][0]) == len(self._data[i][-1]):
                self._data[i][0][last_index] *= scale_factor
        self._scale = other
        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != 2 + (1 if isinstance(make_value(bin_), tuple) and len(make_value(bin_)) > 1 else 0):
        raise ValueError("Number of field_names must match the dimension of the result")

    graph_points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        elif get_coordinate == "middle":
            x = (bin_.left + bin_.right) / 2

        y_values = make_value(bin_)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point = {field_names[0]: x}
        for i, y in enumerate(y_values):
            point[field_names[i + 1]] = y

        graph_points.append(point)

    graph_scale = hist.scale if scale is True else scale

    return {"points": graph_points, "scale": graph_scale}

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import providedBy, Invalid
    import inspect

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True, methods=True))
    required_attributes = set(iface.names(all=True, attributes=True)) - required_methods

    candidate_methods = set(dir(candidate))
    candidate_attributes = {name for name in candidate_methods if not callable(getattr(candidate, name))}

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method_name in missing_methods:
        errors.append(f"Missing method: {method_name}")

    for attr_name in missing_attributes:
        errors.append(f"Missing attribute: {attr_name}")

    for method_name in required_methods.intersection(candidate_methods):
        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(f"Expected method {method_name} to be callable, but it is not")
            continue

        iface_method = iface.get(method_name)
        if iface_method is None:
            continue

        iface_method_signature = inspect.signature(iface_method)
        candidate_method_signature = inspect.signature(method)

        if iface_method_signature != candidate_method_signature:
            errors.append(f"Method {method_name} has incorrect signature. Expected: {iface_method_signature}, Got: {candidate_method_signature}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject as zope_verifyObject
    from zope.interface.verify import verifyClass
    from inspect import signature
    import zope.interface

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    # Check methods
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.method') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Not callable: {name}")
                else:
                    iface_method = iface[name]
                    try:
                        sig = signature(method)
                        iface_sig = signature(iface_method)
                        if not sig.parameters == iface_sig.parameters:
                            errors.append(f"Method {name} has incorrect signature. Expected: {iface_sig}, Got: {sig}")
                    except ValueError as e:
                        errors.append(f"Error checking signature for method {name}: {e}")

    # Check attributes
    for name in iface.names(all=True):
        if iface.get(name).queryTaggedValue('interface.attribute') is not None:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    if not isinstance(iface, type):
        raise ValueError("iface must be a class type")
    if not isinstance(candidate, type):
        raise ValueError("candidate must be a class type")

    try:
        if tentative:
            return issubclass(candidate, iface)
        else:
            return all(hasattr(candidate, attr) for attr in dir(iface) if not attr.startswith('__'))
    except TypeError:
        return False

def determineMetaclass(bases, explicit_mc=None):
    if not isinstance(bases, tuple):
        raise TypeError("bases must be a tuple")

    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("explicit_mc must be a type or None")

    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if not isinstance(base, type):
            raise TypeError("All bases must be types")
        metaclass = type(base)
        if metaclass not in metaclasses:
            metaclasses.add(metaclass)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Find a common metaclass
    for m in metaclasses:
        if all(issubclass(c, m) for c in metaclasses):
            return m

    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

