def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        pass

    try:
        # Try to parse as XRD
        root = ET.fromstring(document)
        if root.tag.endswith('XRD'):
            links = []
            for link in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                link_data = {}
                for attr, value in link.attrib.items():
                    link_data[attr] = value
                links.append(link_data)
            return {"links": links}
    except ET.ParseError:
        pass

    raise ValueError("Document is not in a valid JSON or XRD format")

