def _include_groups(self, parser_dict):
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    if 'include' not in parser_dict:
        return parser_dict

    include_directive = parser_dict['include']
    if not isinstance(include_directive, list):
        raise ValueError("include directive must be a list")

    for group in include_directive:
        if not isinstance(group, str):
            raise ValueError("Each item in the include directive must be a string")

        # Assuming there is a method to fetch group data, e.g., self._fetch_group_data(group)
        try:
            group_data = self._fetch_group_data(group)
        except Exception as e:
            raise RuntimeError(f"Failed to fetch data for group {group}: {e}")

        if not isinstance(group_data, dict):
            raise ValueError(f"Fetched data for group {group} is not a dictionary")

        parser_dict.update(group_data)

    del parser_dict['include']
    return parser_dict

