            raise ValueError(f"Each argument must be a dictionary with 'value', 'min', and 'max' keys. Invalid entry for {arg_name}.")

        value = arg_info['value']
        min_value = arg_info['min']
        max_value = arg_info['max']

        if not isinstance(value, (int, float)) or not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
            raise ValueError(f"Values for 'value', 'min', and 'max' must be numbers. Invalid entry for {arg_name}.")

